; ---------------------------------------------------------------
; void __near__ process_controller (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_process_controller: near

.segment	"CODE"

;
; if(target_mask != 0 && (powerpad_new & target_mask) && target_x <= TARGET_HIT_X){
;
	lda     _target_mask
	ora     _target_mask+1
	beq     L4C3F
	lda     _target_mask
	and     _powerpad_new
	pha
	lda     _target_mask+1
	and     _powerpad_new+1
	sta     tmp1
	pla
	ora     tmp1
	beq     L4C3F
	lda     _target_x
	cmp     #$C9
	bcs     L4C3F
;
; score_to_add = (unsigned char)(1u + streak);
;
	lda     _streak
	clc
	adc     #$01
	sta     _score_to_add
;
; add_score();
;
	jsr     _add_score
;
; add_streak_hit();
;
	jsr     _add_streak_hit
;
; spawn_target_button();
;
	jsr     _spawn_target_button
;
; if((debug_controller_new & (PAD_A | PAD_B)) || (powerpad_new & 0x0fff)){
;
L4C3F:	lda     _debug_controller_new
	and     #$C0
	bne     L4C40
	lda     _powerpad_new+1
	and     #$0F
	sta     tmp1
	lda     _powerpad_new
	ora     tmp1
	bne     L4C40
	rts
;
; add_step();
;
L4C40:	jmp     _add_step

.endproc

